package api.publica;
import java.util.List;import api.publica.PagoClienteDTO.*;import servicio.*;import negocio.*;
public class PagoClienteCuentaService {private final CuentaClienteService cuenta;private final CapacidadesPagoService capacidades;private final CreacionOrdenPagoClienteService creacion;private final ConsultaOrdenPagoClienteService consulta;public PagoClienteCuentaService(){this(new CuentaClienteService(),new CapacidadesPagoService(),new CreacionOrdenPagoClienteService(),new ConsultaOrdenPagoClienteService());}public PagoClienteCuentaService(CuentaClienteService c,CapacidadesPagoService cp,CreacionOrdenPagoClienteService cr,ConsultaOrdenPagoClienteService co){if(c==null||cp==null||cr==null||co==null)throw new IllegalArgumentException("Las dependencias son obligatorias.");cuenta=c;capacidades=cp;creacion=cr;consulta=co;}public CapacidadesPago capacidades(){return capacidades.obtener();}public HistorialOrdenes historial(long clienteId,long reservaId){cuenta.buscarReserva(clienteId,reservaId);return consulta.historial(reservaId);}public OrdenPagoPublica actual(long clienteId,long reservaId){List<OrdenPagoPublica> ordenes=historial(clienteId,reservaId).ordenes();return ordenes.stream().filter(x->x.requiereActualizacion()||"APROBADA".equals(x.estado())).findFirst().orElse(ordenes.isEmpty()?null:ordenes.getFirst());}public OrdenPagoPublica crear(long clienteId,long reservaId,String metodo){var r=cuenta.buscarReserva(clienteId,reservaId);if(!r.pendiente())throw new IllegalArgumentException("La reserva ya no admite una orden de seña.");String elegido=metodo==null||metodo.isBlank()?"TRANSFERENCIA_MANUAL":metodo.trim().toUpperCase();OrdenPago o=switch(elegido){case "TRANSFERENCIA_MANUAL"->creacion.crearManual(reservaId,r.importeSenia(),r.vencimiento());case "PAGO_ONLINE"->creacion.crearOnline(reservaId,r.importeSenia(),r.vencimiento(),"Seña de reserva "+r.cancha());default->throw new IllegalArgumentException("El método de pago no es válido.");};return consulta.convertir(o);}public OrdenPagoPublica crearManual(long clienteId,long reservaId){return crear(clienteId,reservaId,"TRANSFERENCIA_MANUAL");}}
